(function () { var p = products.find(function (x) { return x.id === 2; }); if (p) p.detailHtml = "<h3>경주로를 달리던 말이 손안으로 (예시)</h3><p>대한민국 대표 경주마를 모티브로 만든 명마당 인형이에요. 좋아하는 말과 집으로 함께 돌아가요.</p><p><img src=\"data:image/jpeg;base64,\" alt=\"회색 털과 보라색 굴레를 한 닉스고 인형\"></p><blockquote>경주로를 달린 말의 털빛과 갈기, 굴레 색을 옮겨 왔어요.</blockquote><p>멀리서 봐도 어떤 말인지 알아볼 수 있어요. 안장의 번호와 이름을 보면 경주에서 만났던 말이 바로 떠올라요.</p><h3>안장에 적힌 번호와 이름</h3><p>닉스고, 글로벌히트, 한센. 말마다 안장 색과 번호가 달라요.</p><p><img src=\"data:image/jpeg;base64,\" alt=\"빨간 안장에 4번과 글로벌히트 이름이 적힌 인형\"></p><h3>좋아하는 말부터 모으는 재미</h3><blockquote>응원하는 말부터 한 마리씩 데려가 보세요.</blockquote><p><img src=\"data:image/jpeg;base64,\" alt=\"경주 사진 카드 앞에 나란히 놓인 인형들\"></p><p>대표 경주마들이 한 줄로 모이면 작은 경주가 시작돼요.</p><p><img src=\"data:image/jpeg;base64,\" alt=\"말마와 친구들\"></p><h3>말마 친구들을 만나보세요</h3><p>렛츠런파크 곳곳에서 만나는 말마와 친구들이에요. <a href=\"https://www.kra.co.kr/letsrunPlay/detail/detail-mall-friends-store.html\">말마프렌즈스토어 보기</a></p><h3>자세히 보기</h3><p><img src=\"data:image/jpeg;base64,\" alt=\"닉스고 인형\"></p><p><img src=\"data:image/jpeg;base64,\" alt=\"글로벌히트 인형\"></p><p><img src=\"data:image/jpeg;base64,\" alt=\"한센 인형\"></p><h3>상품 정보</h3><ul><li><strong>구성</strong>(내용 필요)</li><li><strong>크기</strong>(내용 필요)</li><li><strong>소재</strong>(내용 필요)</li><li><strong>제조국</strong>(내용 필요)</li></ul>"; })();
